/**
 * Lazy, cached access to an agency's full schematic in the browser.
 *
 * The eager catalog carries only the light index (`AgencyLightIndex`); the
 * heavy geometry lives in one dynamic-import chunk per agency, generated by
 * `scripts/lib/agency-schematics-vite-plugin.ts`. Each chunk decodes through
 * the same schema the catalog uses and is then memoized for the session.
 */
import * as Schema from "effect/Schema";
import { agencySchematicLoaders } from "virtual:agency-schematics";
import { SchematicSchema, type Schematic } from "~/agencies/types";

const decoded = new Map<string, Schematic>();
const inflight = new Map<string, Promise<Schematic | undefined>>();

/** The decoded schematic when it is already loaded, otherwise undefined. */
export function peekSchematic(agencyId: string): Schematic | undefined {
  return decoded.get(agencyId);
}

/** Registers an already-decoded schematic (catalog entries and tests). */
export function primeSchematic(agencyId: string, schematic: Schematic): void {
  decoded.set(agencyId, schematic);
}

/**
 * Loads (once) and returns an agency's schematic; undefined for mapless
 * agencies. A failed import is forgotten so the next call retries.
 */
export function loadSchematic(agencyId: string): Promise<Schematic | undefined> {
  const ready = decoded.get(agencyId);
  if (ready) return Promise.resolve(ready);
  const pending = inflight.get(agencyId);
  if (pending) return pending;
  const loader = agencySchematicLoaders[agencyId];
  if (!loader) return Promise.resolve(undefined);
  const promise = loader()
    .then((raw) => {
      const schematic = Schema.decodeUnknownSync(SchematicSchema)(raw);
      decoded.set(agencyId, schematic);
      return schematic;
    })
    .finally(() => {
      inflight.delete(agencyId);
    });
  inflight.set(agencyId, promise);
  return promise;
}
